// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
type Small is uint32;
enum Choice { A, B, C }
contract Base {
    uint128 a;
    uint64 b;
    uint24 transient tempA;
}
contract Layout is Base layout at 42 {
    struct Inner { uint128 x; uint64 y; }
    struct Data {
        Inner inner;
        uint256[] values;
        mapping(address owner => uint256 amount) balances;
    }
    uint64 c;
    Data data;
    uint8[40] fixedValues;
    bytes blob;
    string text;
    mapping(address owner => uint256 amount) totals;
    Choice choice;
    Small small;
    uint256 constant K = 1;
    uint256 immutable I = 2;
    int24 transient tempB;
    uint8 transient tempC;
}
